#import <Foundation/Foundation.h>
#import <Vision/Vision.h>
int main(int argc,const char **argv){@autoreleasepool{NSMutableDictionary *all=[NSMutableDictionary dictionary];for(int i=1;i<argc;i++){VNImageRequestHandler *h=[[VNImageRequestHandler alloc]initWithURL:[NSURL fileURLWithPath:@(argv[i])] options:@{}];VNDetectHumanBodyPoseRequest *r=[VNDetectHumanBodyPoseRequest new];NSError *err=nil;[h performRequests:@[r] error:&err];NSMutableArray *people=[NSMutableArray array];for(VNHumanBodyPoseObservation *o in r.results){NSMutableDictionary *pts=[NSMutableDictionary dictionary];NSDictionary *points=[o recognizedPointsForGroupKey:VNHumanBodyPoseObservationJointsGroupNameAll error:&err];for(NSString *k in points){VNRecognizedPoint *p=points[k];pts[k]=@[@(p.x),@(1-p.y),@(p.confidence)];}[people addObject:pts];}all[@(argv[i])]=people;}NSData *d=[NSJSONSerialization dataWithJSONObject:all options:NSJSONWritingPrettyPrinted error:nil];puts([[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding].UTF8String);}}
